import{_ as e,c as a,o as i,aj as r}from"./chunks/framework.CMWtagCP.js";const h=JSON.parse('{"title":"database","description":"","frontmatter":{"title":"database","hugoSource":"computer-science/database/database.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/database/2026-11-17-database.md","filePath":"computer-science/database/2026-11-17-database.md"}'),d={name:"computer-science/database/2026-11-17-database.md"};function o(c,l,s,u,t,n){return i(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="database" tabindex="-1">database <a class="header-anchor" href="#database" aria-label="Permalink to “database”">​</a></h1><h2 id="索引-index" tabindex="-1">索引 index <a class="header-anchor" href="#索引-index" aria-label="Permalink to “索引 index”">​</a></h2><h3 id="什么是聚集索引、非聚集索引" tabindex="-1">什么是聚集索引、非聚集索引？ <a class="header-anchor" href="#什么是聚集索引、非聚集索引" aria-label="Permalink to “什么是聚集索引、非聚集索引？”">​</a></h3><ul><li>聚集索引：数据行的<strong>物理存储顺序</strong>与<strong>索引的逻辑顺序</strong>一致</li><li>非聚集索引：数据行的<strong>物理存储顺序</strong>与<strong>索引的逻辑顺序</strong>不一致</li></ul><h3 id="为什么只能有一种聚集索引" tabindex="-1">为什么只能有一种聚集索引？ <a class="header-anchor" href="#为什么只能有一种聚集索引" aria-label="Permalink to “为什么只能有一种聚集索引？”">​</a></h3><ul><li>因为数据物理的存储顺序只能有一种，因此只能有一种聚集索引</li></ul><h3 id="默认的聚集索引是什么" tabindex="-1">默认的聚集索引是什么？ <a class="header-anchor" href="#默认的聚集索引是什么" aria-label="Permalink to “默认的聚集索引是什么？”">​</a></h3><ul><li>主键</li></ul><h3 id="什么是回表" tabindex="-1">什么是回表？ <a class="header-anchor" href="#什么是回表" aria-label="Permalink to “什么是回表？”">​</a></h3><ul><li>当查询条件使用普通索引并且查询的列不包含在索引中，就需要查询完普通索引后再去查询聚集索引的树拿到完整的行数据</li></ul><h3 id="当底层建了abc的联合索引-底层会建a-ab-abc这3个索引么" tabindex="-1">当底层建了abc的联合索引，底层会建a,ab, abc这3个索引么？ <a class="header-anchor" href="#当底层建了abc的联合索引-底层会建a-ab-abc这3个索引么" aria-label="Permalink to “当底层建了abc的联合索引，底层会建a,ab, abc这3个索引么？”">​</a></h3><ul><li>不会，只创建一个联合索引树</li></ul><h3 id="联合索引-abc-当查询ab-ac会走索引么" tabindex="-1">联合索引（abc)，当查询ab, ac会走索引么？ <a class="header-anchor" href="#联合索引-abc-当查询ab-ac会走索引么" aria-label="Permalink to “联合索引（abc)，当查询ab, ac会走索引么？”">​</a></h3><ul><li>ab 走索引</li><li>ac 只走 a 索引</li></ul><h3 id="order-by-和-group-by-如何创建索引" tabindex="-1">order by 和 group by 如何创建索引？ <a class="header-anchor" href="#order-by-和-group-by-如何创建索引" aria-label="Permalink to “order by 和 group by 如何创建索引？”">​</a></h3><ul><li>order by <ul><li>单列 直接创建</li><li>多列 创建联合索引, 索引顺序要和 order by 的顺序一致 <ul><li>不一致索引会失效</li></ul></li></ul></li><li>group by <ul><li>group by 实际上是先进行排序，再进行分组。所以遵循 order by 的索引机制</li></ul></li></ul><h3 id="mysql索引失效的20种场景" tabindex="-1">MySQL索引失效的20种场景 <a class="header-anchor" href="#mysql索引失效的20种场景" aria-label="Permalink to “MySQL索引失效的20种场景”">​</a></h3><ul><li><a href="https://zhuanlan.zhihu.com/p/10448449924" target="_blank" rel="noreferrer">MySQL索引失效的20种场景</a></li><li>1 查询条件未使用索引列 <ul><li><code>SELECT * FROM users WHERE non_indexed_column = &#39;example&#39;</code></li></ul></li><li>2 查询条件对索引列使用了函数或表达式 <ul><li><code>SELECT * FROM users WHERE LEFT(name, 3) = &#39;Ali&#39;</code></li></ul></li><li>3 数据类型不一致引发隐式类型转换 <ul><li><code>SELECT * FROM users WHERE phone = 1234567890; -- phone 是 VARCHAR</code></li></ul></li><li>4 联合索引使用时的范围查询阻断 <ul><li><code>SELECT * FROM users WHERE name = &#39;Alice&#39; AND age &gt; 30 AND city = &#39;New York&#39;</code></li></ul></li><li>5 如果 OR 条件中有字段未使用索引，会导致整体索引失效 <ul><li><code>SELECT * FROM users WHERE name = &#39;Alice&#39; OR age = 30;</code></li><li>解决方法：拆分查询，用 UNION 替代 <ul><li><code>SELECT * FROM users WHERE name = &#39;Alice&#39; UNION SELECT * FROM users WHERE age = 30;</code></li></ul></li></ul></li><li>6 LIKE 查询中使用前置通配符 <code>%</code> 时，无法利用索引 <ul><li><code>SELECT * FROM users WHERE name LIKE &#39;%Alice&#39;;</code></li><li>解决方法 <ul><li>替换为后置通配符 LIKE &#39;Alice%&#39;</li><li>使用全文索引 <ul><li><code>ALTER TABLE users ADD FULLTEXT(name);</code></li><li><code>SELECT * FROM users WHERE MATCH(name) AGAINST(&#39;Alice&#39;);</code></li></ul></li></ul></li></ul></li><li>7 不等值操作符 <code>!= &lt;&gt;</code> 通常会导致索引失效 <ul><li><code>SELECT * FROM users WHERE age != 30;</code></li><li>解决方法：改写为范围查询 <ul><li><code>SELECT * FROM users WHERE age &lt; 30 OR age &gt; 30;</code></li></ul></li></ul></li><li>8 <code>IN</code> 子句中参数过多时，索引可能失效 <ul><li><code>SELECT * FROM users WHERE id IN (1, 2, ..., 10000)</code></li><li>解决方法：分批查询或控制 IN 参数数量 <ul><li><code>SELECT * FROM users WHERE id BETWEEN 1 AND 5000</code></li></ul></li></ul></li><li>9 某些情况下对NULL值的查询可能导致索引失效 <ul><li><code>SELECT * FROM users WHERE email IS NULL;</code></li><li>解决方法：避免使用 NULL，改为特定占位值</li></ul></li><li>10 ORDER BY 和 GROUP BY 不符合索引顺序 <ul><li><code>select * from users order by age, name;</code> 索引顺序为(name,age)</li><li>解决方法：调整查询或索引顺序一致</li></ul></li><li>11 索引列未覆盖查询字段 <ul><li><code>select age from users where name = &#39;Alice&#39;</code></li><li>解决方法：创建覆盖索引 <ul><li><code>alter table users add index(name, age)</code></li></ul></li></ul></li><li>12 表统计信息过期 <ul><li>表的统计信息不准确时，MySQL优化器可能错误选择全表扫描</li><li>解决方法：定期更新统计信息 <ul><li><code>ANALYZE TABLE users</code></li></ul></li></ul></li><li>13 数据分布不均 <ul><li><code>select * from users where gender = &#39;M&#39; -- gender 列 90% 的值相同</code></li><li>解决方法：优化查询字段或调整数据分布</li></ul></li><li>14 子查询未优化 <ul><li>子查询结果集过大时，索引失效</li><li><code>SELECT * FROM users WHERE id IN (SELECT user_id FROM orders WHERE total &gt; 100)</code></li><li>解决方法：改为 JOIN 查询 <ul><li><code>SELECT u.* FROM users u JOIN orders o ON u.id = o.user_id WHERE o.total &gt; 100</code></li></ul></li></ul></li><li>15 锁机制干扰 间隙锁 <ul><li>描述：间隙锁可能阻止索引的高效使用</li><li><code>SELECT * FROM users WHERE id BETWEEN 10 AND 20 FOR UPDATE</code></li><li>解决方法：降低事务隔离级别至 Read Committed(读已提交) <ul><li>可重复读加上间隙锁防止幻读</li></ul></li></ul></li><li>16 索引被动态调整 <ul><li>MySQL优化器动态调整索引，可能选择非最佳索引或直接全表扫描</li><li><code>SELECT * FROM users FORCE INDEX (idx_name) WHERE name = &#39;Alice&#39;</code></li></ul></li><li>17 聚合函数未走索引 <ul><li>使用聚合函数(如 <code>COUNT</code>, <code>SUM</code>) 时，索引可能无法被利用</li><li><code>SELECT COUNT(*) FROM users WHERE age &gt; 30</code></li><li>解决方法：利用覆盖索引 <ul><li><code>ALTER TABLE users ADD INDEX(age)</code></li></ul></li></ul></li><li>18 使用了非等值JOIN <ul><li><code>select * from users u join orders o on u.id &gt; o.user_id</code></li><li>优化连接条件，尽量使用等值连接</li></ul></li><li>19 小表全表扫描替代索引扫描 <ul><li>对于非常小的表，MySQL优化器可能选择全表扫描而非索引</li><li><code>SELECT * FROM small_table WHERE id = 1;</code></li><li>解决方法：无需优化，小表全表扫描的代价通常可以忽略</li></ul></li><li>20 分区表查询不走全局索引 <ul><li>分区表的查询条件不覆盖分区键时，全局索引可能无法生效</li><li><code>SELECT * FROM partitioned_users WHERE city = &#39;New York&#39;</code></li><li>解决方法：在分区键上创建局部索引</li></ul></li></ul><h3 id="分区表的索引如何创建" tabindex="-1">分区表的索引如何创建 <a class="header-anchor" href="#分区表的索引如何创建" aria-label="Permalink to “分区表的索引如何创建”">​</a></h3><h2 id="分区" tabindex="-1">分区 <a class="header-anchor" href="#分区" aria-label="Permalink to “分区”">​</a></h2><h3 id="分表和分区在物理存储上有什么区别" tabindex="-1">分表和分区在物理存储上有什么区别？ <a class="header-anchor" href="#分表和分区在物理存储上有什么区别" aria-label="Permalink to “分表和分区在物理存储上有什么区别？”">​</a></h3><ul><li>在数据库中一张表对应磁盘中的2个文件，拓展名为<strong>idb</strong>的文件和拓展名为<strong>frm</strong>的文件，idb文件存储表中的记录，frm存储表的结构信息</li><li>进行分表的话有几张表就有几个对应的文件，进行分区就只有一个frm文件和若干个idb文件，一个分区对应一个idb文件</li><li>分区能提升大表的读写性能就是因为根据分区规则仅仅扫描对应分区的磁盘文件，而不用进行全表扫描</li></ul><h3 id="一张表最多可以分多少个区" tabindex="-1">一张表最多可以分多少个区？ <a class="header-anchor" href="#一张表最多可以分多少个区" aria-label="Permalink to “一张表最多可以分多少个区？”">​</a></h3><ul><li>1024</li></ul><h2 id="事务" tabindex="-1">事务 <a class="header-anchor" href="#事务" aria-label="Permalink to “事务”">​</a></h2><h3 id="数据隔离级别" tabindex="-1">数据隔离级别 <a class="header-anchor" href="#数据隔离级别" aria-label="Permalink to “数据隔离级别”">​</a></h3><ul><li>读未提交 <strong>Read Uncommitted</strong></li><li>读已提交 <strong>Read Committed</strong><ul><li>脏读：同一个事务中，多次读取同一数据的结果不同</li></ul></li><li>可重复读 <strong>Repeatable Read</strong><ul><li>幻读：同一个事务中，相同的查询条件读取到的数据条数不一样</li></ul></li><li>串行化 <strong>Serializable</strong></li></ul><h2 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to “MVCC”">​</a></h2><h3 id="mvcc-的全称是什么" tabindex="-1">MVCC 的全称是什么？ <a class="header-anchor" href="#mvcc-的全称是什么" aria-label="Permalink to “MVCC 的全称是什么？”">​</a></h3><ul><li>Multi-Version Concurrency Control 多版本并发控制</li></ul><h3 id="mysql的事务引擎仅仅使用行级锁吗" tabindex="-1">MySQL的事务引擎仅仅使用行级锁吗？ <a class="header-anchor" href="#mysql的事务引擎仅仅使用行级锁吗" aria-label="Permalink to “MySQL的事务引擎仅仅使用行级锁吗？”">​</a></h3><ul><li>不是，它结合了行级锁+MVCC(多版本并发控制)</li></ul><h3 id="mvcc适用于哪些隔离级别" tabindex="-1">MVCC适用于哪些隔离级别？ <a class="header-anchor" href="#mvcc适用于哪些隔离级别" aria-label="Permalink to “MVCC适用于哪些隔离级别？”">​</a></h3><ul><li>适用于 <code>REPEATED READ</code> 和 <code>READ COMMITTED</code></li><li>不适用于 <code>READ UNCOMMITTED</code></li></ul>',34)])])}const b=e(d,[["render",o]]);export{h as __pageData,b as default};
